SINA_SMART["immuno1-testing"] = {"lecture":"immuno1-testing","title":"Immunological testing: diagnostic techniques","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"immuno1-testing:e0","text":"Ag-Ab binding: epitope-paratope, steric complementarity, non-covalent forces.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e1","text":"Visible: precipitation (soluble Ag), agglutination (particulate Ag).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e3","text":"Equivalence zone: maximal precipitation.","topic":"Precipitation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e4","text":"Oudin: simple immunodiffusion; Mancini: radial (quantitative); Ouchterlony: double.","topic":"Precipitation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e5","text":"Immunoelectrophoresis: electrophoresis + antiserum → arcs.","topic":"Precipitation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e6","text":"ABO grouping: direct agglutination.","topic":"Agglutination","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e7","text":"Coombs test: autoimmune haemolysis, transfusion, haemolytic disease of the newborn.","topic":"Agglutination","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e2","text":"Labelled: immunofluorescence, ELISA/Western blot, RIA; ng-pg/mL sensitivity.","topic":"Labelled techniques","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e8","text":"ELISA: direct (Ag), indirect (Ab), sandwich.","topic":"Labelled techniques","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-testing:e9","text":"HIV: ELISA ×2 then Western blot to confirm.","topic":"Labelled techniques","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"xub3vc":"a","u9ilk9":"a","15dy8bw":"a","14ejkpq":"a","qhhb49":"a","frdio9":"a","18ldk0b":"a","8tlcp6":"a","ohuttp":"a","73ki8l":"a","1ue2i7x":"a","y2awlm":"a","1lexvpe":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"immuno1-testing:e0":{"s":0,"u":["Ag-Ab binding: epitope-paratope, steric complementarity, non-covalent forces.","Diagnostic immunology relies on the antigen-antibody reaction : a bimolecular association, like enzyme and substrate, between epitope and paratope , requiring perfect steric complementarity and held by non-covalent forces (ionic, hydrogen, hydrophobic, Van der Waals), forming an immune complex ."],"dp":[]},"immuno1-testing:e1":{"s":0,"u":["Visible: precipitation (soluble Ag), agglutination (particulate Ag).","Techniques are directly visible (precipitation, agglutination) or need labelling (fluorescence, enzymes, isotopes), which is far more sensitive (ng/mL to pg/mL)."],"dp":[]},"immuno1-testing:e3":{"s":1,"u":["Equivalence zone: maximal precipitation.","In liquid, the largest precipitable complexes form in the equivalence zone ; excess of either reagent makes smaller, less precipitable complexes (depends on pH, ionic strength, temperature)."],"dp":[]},"immuno1-testing:e4":{"s":1,"u":["Oudin: simple immunodiffusion; Mancini: radial (quantitative); Ouchterlony: double.","In gel (agar, agarose): simple immunodiffusion (Oudin) : antibody in the gel, a precipitation ring reveals the antigen; radial immunodiffusion (Mancini) : ring diameter measures antigen concentration against standards; double immunodiffusion (Ouchterlony) : antigen and antibodies diffuse toward each other and form precipitation lines; immunoelectrophoresis : serum proteins are separated by electrophoresis, then an antiserum is added in a trough, giving arcs (IgG, IgA, IgM, albumin) to compare with a control."],"dp":[]},"immuno1-testing:e5":{"s":1,"u":["Immunoelectrophoresis: electrophoresis + antiserum → arcs.","In gel (agar, agarose): simple immunodiffusion (Oudin) : antibody in the gel, a precipitation ring reveals the antigen; radial immunodiffusion (Mancini) : ring diameter measures antigen concentration against standards; double immunodiffusion (Ouchterlony) : antigen and antibodies diffuse toward each other and form precipitation lines; immunoelectrophoresis : serum proteins are separated by electrophoresis, then an antiserum is added in a trough, giving arcs (IgG, IgA, IgM, albumin) to compare with a control."],"dp":[]},"immuno1-testing:e6":{"s":2,"u":["ABO grouping: direct agglutination.","ABO blood grouping with anti-A and anti-B.","Active (direct) : the antigen belongs to the particle, e.g."],"dp":[]},"immuno1-testing:e7":{"s":2,"u":["Coombs test: autoimmune haemolysis, transfusion, haemolytic disease of the newborn.","Artificial : the Coombs (anti-globulin) test , used for autoimmune haemolytic anaemia , transfusion compatibility and feto-maternal incompatibility (haemolytic disease of the newborn)."],"dp":[]},"immuno1-testing:e2":{"s":3,"u":["Labelled: immunofluorescence, ELISA/Western blot, RIA; ng-pg/mL sensitivity.","HIV testing : ELISA first, repeated if positive, then Western blot to confirm, because ELISA can give false positives .","Immunofluorescence : antigen or antibody labelled with a fluorochrome, direct or indirect; takes under 3 hours; read with a fluorescence microscope or flow cytometer ."],"dp":[]},"immuno1-testing:e8":{"s":3,"u":["ELISA: direct (Ag), indirect (Ab), sandwich.","Immunoenzymology (ELISA) : an enzyme label turns a colourless substrate into a coloured product read by optical density ; formats: direct (detects antigen), indirect (detects antibody, e.g. anti-HIV) and sandwich .","Immunofluorescence : antigen or antibody labelled with a fluorochrome, direct or indirect; takes under 3 hours; read with a fluorescence microscope or flow cytometer ."],"dp":[]},"immuno1-testing:e9":{"s":3,"u":["HIV: ELISA ×2 then Western blot to confirm.","HIV testing : ELISA first, repeated if positive, then Western blot to confirm, because ELISA can give false positives ."],"dp":[{"h":"Why HIV screening uses two different tests","t":"ELISA is chosen for screening because it is sensitive and cheap: it rarely misses an infected person, but some cross-reacting antibodies give false positives. Western blot is more specific: it shows which viral proteins the antibodies recognise, separated by size, so a true infection gives a characteristic pattern of bands. Combining a sensitive screen with a specific confirmation avoids wrongly telling someone they are infected. Source: the tutorial's ELISA and Western blot slides."}]}},"meta":{"xub3vc":{"a":"recall","vg":"immuno1-testing:e0/recall/1"},"u9ilk9":{"a":"recall","vg":"immuno1-testing:e3/recall/1"},"15dy8bw":{"a":"recall","vg":"immuno1-testing:e3/recall/2"},"14ejkpq":{"a":"recall","vg":"immuno1-testing:e4/recall/1"},"qhhb49":{"a":"recall","vg":"immuno1-testing:e4/recall/2"},"frdio9":{"a":"recall","vg":"immuno1-testing:e6/recall/1"},"18ldk0b":{"a":"recall","vg":"immuno1-testing:e7/recall/1"},"8tlcp6":{"a":"recall","vg":"immuno1-testing:e1/recall/1"},"ohuttp":{"a":"recall","vg":"immuno1-testing:e2/recall/1"},"73ki8l":{"a":"recall","vg":"immuno1-testing:e8/recall/1"},"1ue2i7x":{"a":"recall","vg":"immuno1-testing:e8/recall/2"},"y2awlm":{"a":"recall","vg":"immuno1-testing:e9/recall/1"},"1lexvpe":{"a":"relationship","vg":"immuno1-testing:e9/relationship/1"}},"explRev":"a9e0a7ce22ee"};
